import sys

def main():
    sums = {}
    stdin = sys.stdin.buffer
    stdin.readline() # skip header
    for line in stdin:
        # id,cat,val
        c1 = line.find(b',')
        c2 = line.find(b',', c1 + 1)
        cat = line[c1+1:c2]
        val = float(line[c2+1:])
        sums[cat] = sums.get(cat, 0.0) + val
    for cat in sorted(sums):
        print(f"{cat.decode()},{sums[cat]:.2f}")

if __name__ == '__main__':
    main()
